const provinces=[...new Set(stations.map(s=>s.province))].sort((a,b)=>a.localeCompare(b,'zh'));$('province-count').textContent=provinces.length;provinces.forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;$('province-filter').append(o)});
function filteredStations(){let rows=stations.filter(s=>s.name.includes($('station-query').value.trim())&&(!$('province-filter').value||s.province===$('province-filter').value));const sort=$('station-sort').value;if(sort==='price-high')rows.sort((a,b)=>b.price-a.price);if(sort==='price-low')rows.sort((a,b)=>a.price-b.price);return rows}
function showStations(){const rows=filteredStations();$('station-rows').innerHTML=rows.map(s=>`<tr><td>${s.id}</td><td>${s.name}</td><td>${s.province}</td><td>${s.capacity}</td><td>${s.price.toFixed(2)}</td><td>${s.category}</td></tr>`).join('')||'<tr><td colspan="6">没有匹配的电站，请更换搜索条件。</td></tr>';$('sample-count').textContent=`显示 ${rows.length} / 49 条期别记录 · ${new Set(rows.map(s=>s.id)).size} 个原表编号`}
['station-query','province-filter','station-sort'].forEach(id=>$(id).addEventListener('input',showStations));$('sample-export').onclick=()=>{const lines=['原编号,电站或期别,省份,装机容量（万千瓦）,2023含税容量电价（元每千瓦年容量口径）,2023原表分类（非当前状态）,数据来源',...filteredStations().map(s=>`${s.id},${s.name},${s.province},${s.capacity},${s.price.toFixed(2)},${s.category},https://www.ndrc.gov.cn/xwdt/tzgg/202305/P020230515603095829466.pdf`)];const u=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='抽水蓄能电站_2023历史容量电价样本.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};showStations();
const ecoIds=['buy-price','sell-price','round-eff','in-loss','out-loss','variable-cost'];
function economicResult(buy,sell,eff,lin,lout,cost){const eta=eff/100*(1-lin/100)*(1-lout/100);return {eta,energy:1/eta,breakeven:buy/eta+cost,margin:sell-buy/eta-cost}}
function updateEconomic(){if(ecoIds.some(id=>!$(id).value.trim()||!$(id).checkValidity())){$('eco-error').textContent='请在各输入框标注的有效范围内填写数值；效率必须大于0。';['total-eff','input-energy','unit-margin','break-even','margin-explain'].forEach(id=>$(id).textContent='—');$('sensitivity').innerHTML='';return;}$('eco-error').textContent='';const v=ecoIds.map(id=>+$(id).value);const r=economicResult(...v);$('total-eff').textContent=(r.eta*100).toFixed(2)+'%';$('input-energy').textContent=r.energy.toFixed(3)+' kWh';$('unit-margin').textContent=(r.margin>=0?'+':'')+r.margin.toFixed(3)+' 元';$('unit-margin').classList.toggle('negative',r.margin<0);$('margin-explain').textContent=r.margin>=0?'变动贡献为正：可用于覆盖固定成本，但尚不能判断项目盈利。':'变动贡献为负：本情景的售电收入不足以覆盖购电和所填其他变动费用。';$('break-even').textContent='变动保本售价：'+r.breakeven.toFixed(3)+' 元/kWh';$('sensitivity').innerHTML=[0,2,5].map(loss=>{const t=economicResult(v[0],v[1],v[2],loss,loss,v[5]);return `<tr><td>${loss}% / ${loss}%</td><td>${(t.eta*100).toFixed(2)}%</td><td>${t.breakeven.toFixed(3)} 元/kWh</td><td>${t.margin.toFixed(3)} 元/kWh</td></tr>`}).join('')}
ecoIds.forEach(id=>$(id).addEventListener('input',updateEconomic));$('eco-reset').onclick=()=>{[0.30,0.65,75,2,2,0.02].forEach((v,i)=>$(ecoIds[i]).value=v);updateEconomic()};updateEconomic();
